function bestRewrittenProfit(prices: number[], strategy: number[], k: number): number {
  const n = prices.length;
  let base = 0;
  for (let i = 0; i < n; i++) base += strategy[i] * prices[i];
  let best = base;
  for (let l = 0; l + k <= n; l++) {
    let value = base;
    for (let i = l; i < l + k; i++) {
      value -= strategy[i] * prices[i];
      if (i >= l + k / 2) value += prices[i];
    }
    best = Math.max(best, value);
  }
  return best;
}

