function bestRewrittenProfit(prices: number[], strategy: number[], k: number): number {
  const n = prices.length, half = k / 2;
  const earn = new Array(n + 1).fill(0), price = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    earn[i + 1] = earn[i] + strategy[i] * prices[i];
    price[i + 1] = price[i] + prices[i];
  }
  const base = earn[n];
  let best = base;
  for (let l = 0; l + k <= n; l++) {
    const value = base - (earn[l + k] - earn[l]) + (price[l + k] - price[l + half]);
    best = Math.max(best, value);
  }
  return best;
}

